import{describe,it,expect,beforeAll}from"vitest";import{readFileSync}from"node:fs";import{resolve,dirname}from"node:path";import{fileURLToPath}from"node:url";const __dirname=dirname(fileURLToPath(import.meta.url));function loadPvcData(){const e=readFileSync(resolve(__dirname,"../../frontend/param-vir-chakra-explorer/pvc-data.js"),"utf-8");return new Function(e+"\nreturn { PVC_INFO, MEDAL_HISTORY, PVC_ELIGIBILITY, PVC_SELECTION_PROCESS, PVC_BATTLES, PVC_HEROES, CONFLICTS_TIMELINE };")()}describe("Param Vir Chakra Gallery & Heroes Explorer — Data & Integration Tests",()=>{let e;beforeAll(()=>{e=loadPvcData()}),describe("PVC_INFO metadata",()=>{it("contains correct award metadata and total awardees count",()=>{expect(e.PVC_INFO.id).toBe("param-vir-chakra"),expect(e.PVC_INFO.totalRecipients).toBe(21),expect(e.PVC_INFO.designer).toContain("Savitri Khanolkar"),expect(e.PVC_INFO.symbolism).toContain("Vajra")}),it("has quickStats array with 6 items",()=>{expect(Array.isArray(e.PVC_INFO.quickStats)).toBe(!0),expect(e.PVC_INFO.quickStats.length).toBe(6)})}),describe("MEDAL_HISTORY",()=>{it("contains overview, design origin, and motto",()=>{expect(e.MEDAL_HISTORY.overview).toBeDefined(),expect(e.MEDAL_HISTORY.designOrigin).toBeDefined(),expect(e.MEDAL_HISTORY.motto).toBeDefined()})}),describe("PVC_ELIGIBILITY & SELECTION",()=>{it("defines eligibility categories and selection process steps",()=>{expect(Array.isArray(e.PVC_ELIGIBILITY.categories)).toBe(!0),expect(e.PVC_ELIGIBILITY.categories.length).toBe(4),expect(Array.isArray(e.PVC_SELECTION_PROCESS.steps)).toBe(!0),expect(e.PVC_SELECTION_PROCESS.steps.length).toBe(5)})}),describe("PVC_BATTLES",()=>{it("contains famous battles and military operations",()=>{expect(Array.isArray(e.PVC_BATTLES)).toBe(!0),expect(e.PVC_BATTLES.length).toBeGreaterThanOrEqual(6),expect(e.PVC_BATTLES[0].title).toContain("Badgam")})}),describe("PVC_HEROES catalog",()=>{it("contains all 21 Param Vir Chakra recipients with citations",()=>{expect(Array.isArray(e.PVC_HEROES)).toBe(!0),expect(e.PVC_HEROES.length).toBe(21)}),it("includes Major Somnath Sharma, Captain Vikram Batra, and CQMH Abdul Hamid",()=>{const t=e.PVC_HEROES.find(e=>"somnath-sharma"===e.id),a=e.PVC_HEROES.find(e=>"vikram-batra"===e.id),r=e.PVC_HEROES.find(e=>"abdul-hamid"===e.id);expect(t).toBeDefined(),expect(a).toBeDefined(),expect(r).toBeDefined(),expect(t.famousWords).toContain("last man and the last round"),expect(a.famousWords).toContain("Yeh Dil Maange More")})}),describe("CONFLICTS_TIMELINE",()=>{it("covers 7 major historical conflicts",()=>{expect(Array.isArray(e.CONFLICTS_TIMELINE)).toBe(!0),expect(e.CONFLICTS_TIMELINE.length).toBe(7)})}),describe("Landing Page Integration",()=>{it("is linked correctly from awards-of-india-explorer landing page",()=>{const e=readFileSync(resolve(__dirname,"../../frontend/awards-of-india-explorer/index.html"),"utf-8");expect(e).toContain("../param-vir-chakra-explorer/index.html"),expect(e).toContain("Param Vir Chakra")})})});